preConditionHook:
// THE CORPUS'S LEG COUNTER -- Brooks's high 1 / high 2 / high 3 / high 4 and
// the mirrored low 1..low 4. This is the SETTLED counter of Ranges ch17
// (R17-01) and every other rule in the corpus that counts legs inlines this
// same block rather than referencing this file.
//
// THE DEFINITION (do not re-deliberate; the merge pass chose it over five
// competing ones because it needs no swing pivots, no lookahead and no leg
// definition):
//
//   * A bar whose high exceeds the PRIOR bar's high advances the count -- but
//     only once a new low has formed since the last counted bar. Without that
//     guard a second higher-high bar in the same push would count again, and
//     it is a retest of the one leg, not a new leg.
//   * The count RESETS to 0 the instant the close makes a fresh
//     resetLookback-bar high. That is the concrete stand-in for 'the trend
//     made a new extreme, so the pullback is over'; Brooks fixes no window
//     and 20 is the merged default.
//   * The count SATURATES at 4. Brooks names no high 5.
//
// The reset window is Highest(high, resetLookback)[1] -- the N bars ENDING
// ONE BAR AGO, so the current bar's own high cannot defeat its own reset
// test. Highest/Lowest bottom out in EL's Extremes(), which is EasyLanguage
// SOURCE and so carries the relational tolerance, which is why the scan uses
// el_gt / el_lt and not raw > and <.
//
// The rule FIRES on the bar that advances the count to countTarget: that bar
// is the high-N signal bar, and under the corpus's signal-bar-close /
// next-bar-open convention the fire IS the entry. advHigh is what makes it a
// one-bar event rather than a level -- LegCountAtLeast is the same counter
// read as a standing threshold.
//
// WARM-UP: minLowSince and signalLow start at 0 like every EL variable, so on
// positive prices the first advance can only come through the highCount == 0
// branch, and both values are real prices from the first counted bar on. The
// EasyLanguage twin's variables initialise to the same 0, so the two agree
// bar for bar through warm-up as well.
//
// On a reset the count alone is cleared, exactly as R17-01 states: signalLow
// and minLowSince are left stale deliberately, because the highCount == 0
// branch bypasses them until the next advance overwrites both.
priorHigh = high[1];
priorLow = low[1];
for (int i = 2; i <= (int)resetLookback; ++i) {
    if (el_gt(high[i], priorHigh)) priorHigh = high[i];
    if (el_lt(low[i], priorLow)) priorLow = low[i];
}
advHigh = false;
advLow = false;
if (el_gt(close[0], priorHigh)) {
    highCount = 0;
} else {
    if (el_lt(low[0], minLowSince)) minLowSince = low[0];
    if (el_gt(high[0], high[1]) && (highCount == 0 || el_lt(minLowSince, signalLow))) {
        highCount = highCount + 1;
        if (highCount > 4) highCount = 4;
        signalLow = low[0];
        minLowSince = low[0];
        advHigh = true;
    }
}
if (el_lt(close[0], priorLow)) {
    lowCount = 0;
} else {
    if (el_gt(high[0], maxHighSince)) maxHighSince = high[0];
    if (el_lt(low[0], low[1]) && (lowCount == 0 || el_gt(maxHighSince, signalHigh))) {
        lowCount = lowCount + 1;
        if (lowCount > 4) lowCount = 4;
        signalHigh = high[0];
        maxHighSince = high[0];
        advLow = true;
    }
}
